import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.IOException;
import java.util.Map;
import java.util.Set;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private Map<String, List<String>> comments;

    @InjectMocks
    private CommentsConfiguration commentsConfiguration;

    @Test
    public void [MethodUnderTest]Constructor() {
        // Arrange
        commentsConfiguration.comments = Map.of("path1", Set.of("comment1"));

        // Act
        commentsConfiguration.comments.put("path2", "another comment");

        // Assert
        ObjectMapper mapper = new ObjectMapper();
        Map<String, String> expectedComments = Map.of(
                "path1", "comment1",
                "path2", "another comment"
        );
        Set<String> actualComments = comments.get("path2");
        assertEquals(expectedComments, actualComments);
    }

    @Test
    public void [MethodUnderTest]CommentLinesConstructor() {
        // Arrange
        String path = "path1";
        String... commentLines = {"comment1", "", "another comment"};

        // Act
        commentsConfiguration.setComment(path, commentLines);

        // Assert
        ObjectMapper mapper = new ObjectMapper();
        Map<String, List<String>> expectedComments = Map.of(
                "path1", Set.of("comment1", "another comment")
        );
        assertEquals(expectedComments, comments.get(path));
    }

    @Test
    public void [MethodUnderTest]GetAllComments() {
        // Arrange
        commentsConfiguration.comments.put("path1", Set.of("comment1"));

        // Act
        ObjectMapper mapper = new ObjectMapper();
        Map<String, List<String>> expectedComments = Map.of(
                "path1", Set.of("comment1")
        );

        // Assert
        @Nullable
        Map<String, String> actualComments = comments.getComments();
        assertEquals(expectedComments, actualComments);
    }

    @Test
    public void [MethodUnderTest]GetAllCommentsWithMocking() {
        // Arrange
        ObjectMapper mapper = new ObjectMapper();

        // Act
        Map<String, List<String>> expectedComments = Map.of(
                "path1", Set.of("comment1")
        );
        @Nullable
        Map<String, String> actualComments = comments.getComments();
        assertEquals(expectedComments, actualComments);
    }
}
